	private static final class OpaqueScope extends UnaryTupleOperator {
		private OpaqueScope(TupleExpr arg) {
			super(arg);
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visitor.meetOther(this);
		}
	}

	@Test
	void standardStagesKeepTheirIdentityAndDistinguishParametersFromRuntimeInput() {
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		var pipeline = new StandardQueryOptimizerPipeline(strategy, new EmptyTripleSource(),
				new EvaluationStatistics());
		MapBindingSet parameters = parameters();
		boolean assignmentSeen = false;
		boolean constantsSeen = false;
		for (QueryOptimizer optimizer : pipeline.getOptimizers()) {
			BindingSet input = pipeline.getOptimizerInputBindings(optimizer, parameters);
			if (optimizer instanceof BindingAssignerOptimizer) {
				assignmentSeen = true;
				assertThat(optimizer).isSameAs(StandardQueryOptimizerPipeline.BINDING_ASSIGNER);
				assertThat(input).isSameAs(parameters);
			} else if (optimizer instanceof ConstantOptimizer) {
				constantsSeen = true;
				assertThat(input).isSameAs(parameters);
			} else {
				assertThat(input).isSameAs(EmptyBindingSet.getInstance());
			}
		}
		assertThat(assignmentSeen).isTrue();
		assertThat(constantsSeen).isTrue();
	}

	@Test
	void customPipelineKeepsItsSuppliedBindingContract() {
		MapBindingSet parameters = parameters();
		AtomicReference<BindingSet> observed = new AtomicReference<>();
		QueryOptimizer optimizer = (expression, dataset, bindings) -> observed.set(bindings);
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		strategy.setOptimizerPipeline(() -> List.of(optimizer));
		strategy.optimize(new SingletonSet(), new EvaluationStatistics(), parameters);
		assertThat(observed.get()).isSameAs(parameters);
	}

	private static MapBindingSet parameters() {
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("x", SimpleValueFactory.getInstance().createLiteral(1));
		return bindings;
	}
